rows[132292]={title={{20,802267360},"역전: 어둠의 연소"},description={"^burns an enemy target's soul, inflicting normal damage plus ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%.$","적 대상의 영혼을 태워 일반 공격력에 추가로 \0313\031 동안 \0312\031초마다 \0311\031의 암흑 피해를 입힙니다.",{0,0,1},{1,2,3}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 암흑 피해",{0,0},{1,2}}}
