rows[132294]={title={{22,1716157228},"역전: 비전 충격"},description={"^an arcane%-infused weapon shocks an enemy target, inflicting normal damage plus ([%+%-]?%d[%d,.%+%-to –]*) arcane damage every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%.$","비전의 힘이 깃든 지팡이로 적 대상에게 충격을 주어 일반 공격력에 추가로 \0313\031 동안 \0312\031초마다 \0311\031의 비전 피해를 입힙니다.",{0,0,1},{1,2,3}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) arcane damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 비전 피해",{0,0},{1,2}}}
