rows[135619]={title={{14,1260739550},"승리의 일격"},description={"^a powerful attack that causes ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage to all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yds, and increases their chance to miss by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","강력한 공격으로 \0312\031미터 반경 내 모든 적에게 무기 공격력의 \0311\031%만큼 피해를 입히고, 대상의 공격이 빗나갈 확률을 \0313\031%만큼 증가시킵니다.",{0,0,0},{1,2,3}},aura={"^chance to hit reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","적중률 \0311\031%만큼 감소",{0},{1}}}
rows[135620]={title={{11,173943317},"방패 가격"},description={"^bashes an enemy with the caster's shield, inflicting ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage and interrupting the spell being cast%.$","적을 방패로 가격하여 무기 공격력의 \0311\031%에 해당하는 피해를 입히고 주문 시전을 방해합니다.",{0},{1}}}
