rows[135622]={title={{15,1934126976},"축전 토템"},description={"^summons an air totem with ([%+%-]?%d[%d,.%+%-to –]*) health at the feet of the caster that explodes after ([%+%-]?%d[%d,.]* %a+) sec to stun all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards for ([%+%-]?%d[%d,.]* %a+)%.$","시전자의 위치에 \0311\031의 생명력을 지닌 바람의 토템을 소환합니다. 바람의 토템은 \0312\031초 후에 폭발하여 \0314\031 동안 \0313\031미터 반경 내에 있는 모든 적을 기절시킵니다.",{0,1,0,1},{1,2,3,4}}}
