rows[137174]={title={{6,350654641},"흡수"},description={"^channels possessed blood into the target, destroying the caster and healing the target for ([%+%-]?%d[%d,.%+%-to –]*)%.$","대상에게 지배된 피를 집중해, 시전자를 파괴하며 대상의 생명력을 \0311\031만큼 회복시킵니다.",{0},{1}}}
rows[137175]={title={{16,842522808},"천둥 던지기"},description={"^jin'rokh the breaker throws his current target at a distant mogu statue, breaking the statue and inflicting ([%+%-]?%d[%d,.%+%-to –]*) physical damage%. additionally inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage to other players within ([%+%-]?%d[%d,.%+%-to –]*) yards of the point of impact, stunning them for ([%+%-]?%d[%d,.]* %a+)%.$","파괴자 진로크가 현재 대상을 멀리 있는 모구 석상에 던져, 석상을 부수며 \0311\031의 물리 피해를 입힙니다. 또한 충돌 지점에서 \0313\031미터 반경 내에 있는 다른 플레이어들은 \0312\031의 자연 피해를 입고 \0314\031 동안 기절합니다.",{0,0,0,1},{1,2,3,4}}}
rows[137176]={title={{19,1338187967},"과부하된 회로"},description={"^the conduit was the highest power after becoming supercharged, causing overloaded circuits, disabling the conduit%. inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","도관 초자력 충전 이후에는 도관의 작동이 정지되며, 과부하된 회로 효과가 발생합니다. \0312\031초마다 \0311\031의 자연 피해를 입힙니다.",{0,0},{1,2}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 자연 피해",{0,0},{1,2}}}
